from datetime import time


def create_default_periods(apps, schema_editor):
    Period = apps.get_model('api', 'Period')
    periods = []
    for number in range(1, 9):
        start_minutes = 8 * 60 + (number - 1) * 45
        end_minutes = start_minutes + 45
        periods.append(Period(
            number=number,
            start_time=time(start_minutes // 60, start_minutes % 60),
            end_time=time(end_minutes // 60, end_minutes % 60),
        ))
    Period.objects.using(schema_editor.connection.alias).bulk_create(periods)


